import {extended} from './extended.mjs';
export const tracks = [
 {id:'toefl',name:'TOEFL',tag:'Academic communication',intro:'Explain ideas clearly, connect evidence to claims, and summarize academic information.',lessons:[
 {title:'Explain a cause',goal:'Separate a cause from an outcome and describe the connection.',rule:'A cause explains why something happens. An outcome describes what happens. Use because to introduce a cause and therefore to introduce an outcome. A possible explanation is not automatically proven.',example:'Warmer water holds less dissolved oxygen. Therefore, some fish may struggle to survive.',task:'Identify the cause and the outcome. Then restate the relationship in one sentence.',words:[['consequence','a result of an action or event','A consequence of the drought was a smaller harvest.'],['attribute to','to explain something as the result of a particular cause','Researchers attribute the decline to habitat loss.'],['contribute to','to help cause an outcome without being its only cause','Pollution can contribute to breathing problems.'],['underlying','existing beneath the surface or forming the basic cause','The underlying cause remains uncertain.'],['hypothesis','a proposed explanation that can be tested','The experiment tested a hypothesis about plant growth.'],['therefore','for that reason; as a result','The sample was small; therefore, the conclusion is tentative.']],questions:[['Which phrase introduces a possible cause?',['may result from','is identical to','in contrast'],'may result from','May signals uncertainty; result from introduces a cause.'],['Which claim is best supported by the example?',['Warmer water can affect fish survival.','All fish die in warm water.','Oxygen causes water to become warmer.'],'Warmer water can affect fish survival.','The example describes a possible effect, not a universal outcome.']]},
 {title:'Summarize a lecture',goal:'State a main idea and select supporting details.',rule:'Start with the central claim. Add the strongest supporting detail. Keep the speaker’s degree of certainty and avoid adding your own opinion.',example:'Lecture: Urban trees provide shade and cool streets. Their benefits vary with species and location. Summary: Urban trees can reduce street temperatures, but their effects depend on local conditions.',task:'Give a two-sentence summary: one main idea and one qualification.',words:[['summarize','to state the main points briefly','Summarize the lecture in two sentences.'],['evidence','information that supports or challenges a claim','The speaker presents evidence from three studies.'],['qualify','to limit or make a statement less absolute','The lecturer qualifies the claim by noting regional differences.'],['in contrast','used to introduce a difference','In contrast, the second study found little change.'],['retain','to keep something','A good summary retains the speaker’s main point.'],['illustrate','to explain or show something with an example','The diagram illustrates the process.']],questions:[['What belongs in a summary?',['The main idea and a relevant qualification','Every example in its original order','An unsupported personal opinion'],'The main idea and a relevant qualification','A summary preserves central meaning while removing unnecessary detail.'],['Why keep the word can in the tree example?',['It preserves the limited claim.','It guarantees the effect everywhere.','It removes the main idea.'],'It preserves the limited claim.','Can expresses possibility rather than a universal guarantee.']]}]},
 {id:'toeic',name:'TOEIC',tag:'Workplace English',intro:'Read workplace messages, understand requests, and choose precise business vocabulary.',lessons:[
 {title:'Act on an email',goal:'Find the requested action, responsible person and deadline.',rule:'Read for three things: what must happen, who must do it, and when it is due. Separate background information from the actual request.',example:'Please send the revised proposal to Maya by Thursday. She will review it before Friday’s meeting.',task:'Say the action and deadline aloud without rereading the message.',words:[['proposal','a suggested plan for others to consider','The client requested a revised proposal.'],['deadline','the latest time by which something must be completed','The deadline is Thursday afternoon.'],['confirm','to state that something is correct or agreed','Please confirm your attendance.'],['by Thursday','no later than Thursday','Send the report by Thursday.'],['follow up','to take further action after an earlier contact','I will follow up with the supplier tomorrow.'],['attachment','a file sent with an electronic message','The invoice is in the attachment.']],questions:[['When must the proposal be sent?',['By Thursday','After Friday’s meeting','Whenever Maya asks'],'By Thursday','By marks the latest acceptable time.'],['Who reviews the proposal?',['Maya','The sender’s client','Everyone at the meeting'],'Maya','She refers to Maya in the preceding sentence.']]},
 {title:'Handle a schedule change',goal:'Understand changes and respond politely.',rule:'Identify the original plan, the change and the required response. Use could you for a polite request and distinguish reschedule from cancel.',example:'The training session has been moved to 10 a.m. Could you let us know whether you can attend?',task:'Write a brief reply confirming attendance or asking for another time.',words:[['reschedule','to arrange an event for a different time','We need to reschedule the interview.'],['postpone','to delay something until a later time','The team postponed the launch.'],['available','free or able to be used at a particular time','Are you available at ten?'],['attend','to be present at an event','All new employees should attend the session.'],['let us know','to tell us information we need','Please let us know if your plans change.'],['make arrangements','to organize what is needed for an event or activity','We will make arrangements for your visit.']],questions:[['What happened to the session?',['Its time changed.','It was canceled.','Attendance became optional.'],'Its time changed.','Moved to a new time describes rescheduling, not cancellation.'],['Which reply answers the request?',['Yes, I can attend at 10 a.m.','Training is useful.','I received a report.'],'Yes, I can attend at 10 a.m.','The sender needs to know whether the recipient can attend.']]}]},
 {id:'sat',name:'SAT',tag:'Reading and writing',intro:'Use context, textual evidence and clear logical connections to interpret short passages.',lessons:[
 {title:'Use words in context',goal:'Choose a meaning that fits the surrounding claim.',rule:'Predict the meaning before reading the choices. Check both the sentence’s logic and the word’s tone. A familiar dictionary meaning may not fit this context.',example:'Although early results were promising, later trials produced negligible improvements. Here negligible means too small to matter.',task:'Explain how although creates a contrast.',words:[['negligible','so small that it has little importance','The adjustment had a negligible effect.'],['substantial','large or important in amount or degree','The second treatment produced a substantial improvement.'],['ambiguous','having more than one possible meaning','The instructions were ambiguous.'],['consistent with','in agreement with or fitting existing information','The finding is consistent with earlier research.'],['promising','showing signs of possible future success','The first trial produced promising results.'],['undermine','to weaken the support for something','The new evidence undermines the claim.']],questions:[['What does negligible mean in the example?',['Too small to matter','Extremely harmful','Unexpectedly large'],'Too small to matter','The contrast separates promising expectations from limited improvement.'],['Which word contrasts most directly with negligible?',['Substantial','Ambiguous','Consistent'],'Substantial','Substantial describes a large or important amount.']]},
 {title:'Connect ideas',goal:'Select a transition based on the relationship between claims.',rule:'Use however for contrast, therefore for a supported result, and for example for an illustration. Read both sentences before choosing a transition.',example:'The method is inexpensive. However, it requires more time than the alternative.',task:'Replace however with another contrast marker without changing the meaning.',words:[['however','used to introduce a contrast or limitation','The route is short; however, it is steep.'],['moreover','used to add another supporting point','The tool is accurate; moreover, it is easy to use.'],['consequently','as a result','Demand fell; consequently, production slowed.'],['for instance','used to introduce an example','Some metals, for instance copper, conduct electricity well.'],['nevertheless','despite what has just been stated','The task was difficult; nevertheless, she completed it.'],['transition','a word or phrase that connects ideas','Choose a transition that expresses contrast.']],questions:[['What relationship does the method example express?',['A benefit followed by a limitation','A cause followed by its result','A general claim followed by an example'],'A benefit followed by a limitation','However introduces a drawback after the benefit.'],['Which transition introduces an additional supporting point?',['Moreover','However','Consequently'],'Moreover','Moreover adds support; the other choices mark contrast or a result.']]}]},
 {id:'gmat',name:'GMAT',tag:'Critical reasoning',intro:'Analyze business arguments by identifying assumptions, evidence and alternative explanations.',lessons:[
 {title:'Find an assumption',goal:'Identify the missing link between evidence and a conclusion.',rule:'Separate what the argument states from what it needs to be true. Negate a proposed necessary assumption: if the reasoning collapses, that assumption is important.',example:'A store expects longer opening hours to increase profit because more customers will shop. The argument needs additional revenue to outweigh additional costs.',task:'Name a cost that could weaken the prediction.',words:[['assumption','an unstated idea accepted as true in reasoning','The prediction depends on an assumption about demand.'],['revenue','money received from sales or other business activity','Longer hours may increase revenue.'],['profit','money remaining after costs are subtracted from revenue','Higher revenue does not always mean higher profit.'],['outweigh','to be greater or more important than something else','The benefits must outweigh the costs.'],['overhead','regular costs of running a business','Rent is part of the company’s overhead.'],['break even','to have revenue equal to costs','The store expects to break even this month.']],questions:[['What missing link matters most?',['Extra revenue exceeds extra costs.','Every customer shops at night.','The store sells only one product.'],'Extra revenue exceeds extra costs.','The conclusion concerns profit, which depends on both revenue and costs.'],['Which fact weakens the argument?',['Extra staffing costs exceed added sales revenue.','Several customers prefer later hours.','The store sells popular products.'],'Extra staffing costs exceed added sales revenue.','This directly challenges the predicted increase in profit.']]},
 {title:'Evaluate competing explanations',goal:'Distinguish a correlation from evidence of causation.',rule:'When two things change together, ask whether a third factor explains both. Useful evidence discriminates between the proposed cause and a plausible alternative.',example:'Sales increased after a new advertisement appeared. During the same period, the store also reduced prices. Either change could have influenced sales.',task:'Suggest a comparison that separates the effects of advertising and price.',words:[['correlation','a relationship in which things vary together','A correlation alone does not establish a cause.'],['alternative explanation','another possible account of why something happened','A discount is an alternative explanation for the increase.'],['control for','to account for a factor when making a comparison','The analysis must control for seasonal demand.'],['evaluate','to judge using relevant criteria or evidence','Evaluate the argument before accepting its conclusion.'],['confounding factor','a variable that makes a causal relationship harder to interpret','The simultaneous discount is a confounding factor.'],['comparable','similar enough for a useful comparison','Compare stores with comparable customer bases.']],questions:[['Why is the causal claim uncertain?',['Prices also changed.','Sales were measured.','An advertisement existed.'],'Prices also changed.','The price reduction provides another plausible cause.'],['Which comparison is most useful?',['Similar stores with unchanged prices and different advertising','Two unrelated stores with different products','Sales from a single day without context'],'Similar stores with unchanged prices and different advertising','Holding prices stable helps separate advertising from the competing explanation.']]}]},
 {id:'gre',name:'GRE',tag:'Verbal reasoning',intro:'Read for logical structure, precise meanings and evidence-based interpretation.',lessons:[
 {title:'Follow sentence logic',goal:'Use contrast and support clues before choosing a word.',rule:'Locate words such as although, because and despite. Predict the missing idea. Then test each choice against the whole sentence rather than matching one nearby word.',example:'Although the critic praised the method’s originality, she remained skeptical of its practical value. Praise and doubt refer to different aspects.',task:'Explain why praised and skeptical can appear in the same sentence.',words:[['skeptical','having doubts about a claim or idea','The reviewer was skeptical of the explanation.'],['innovative','introducing new methods or ideas','The team proposed an innovative approach.'],['pragmatic','focused on practical results and circumstances','A pragmatic solution must work with the available budget.'],['despite','without being prevented by something','Despite its originality, the method was difficult to use.'],['concede','to admit a point, often while disagreeing more broadly','The critic conceded that the idea was original.'],['tenable','capable of being defended with reason or evidence','The claim is no longer tenable after the new findings.']],questions:[['What does skeptical express?',['Doubt','Complete agreement','Originality'],'Doubt','The critic questions practical value while recognizing originality.'],['Which clue signals contrast?',['Although','Because','Furthermore'],'Although','Although introduces a concession that contrasts with the main clause.']]},
 {title:'Match meaning, not appearance',goal:'Find two words that preserve the same sentence meaning.',rule:'For sentence-equivalence practice, both selected words must fit the sentence and produce similar meanings. Two synonyms can both be wrong if they conflict with the context.',example:'The speaker was laconic, answering complex questions in only a few words. Concise preserves the intended meaning; evasive adds an unsupported idea of avoidance.',task:'Write a short sentence showing concise without implying unfriendly.',words:[['laconic','using very few words','Her laconic reply contained only three words.'],['concise','expressing information clearly in few words','The summary is concise and accurate.'],['evasive','avoiding a direct answer or commitment','His evasive answer did not address the question.'],['verbose','using more words than necessary','The verbose report could be shortened.'],['equivalent','equal or similar in meaning, value or effect','The two expressions are equivalent in this context.'],['in context','considered with the surrounding information','Interpret the word in context.']],questions:[['Which word best preserves laconic in the example?',['Concise','Evasive','Verbose'],'Concise','Few words supports concise; it does not establish avoidance.'],['Why can a synonym pair be incorrect?',['Both words may conflict with the sentence.','Synonyms always have opposite meanings.','Context never matters.'],'Both words may conflict with the sentence.','The pair must satisfy both contextual fit and similarity of meaning.']]}]}
];
for(const track of tracks)track.lessons.push(...extended[track.id]);
